  const src2 = [
    [200+Math.sin(t*1.2+1)*60, 60+Math.cos(t*0.9)*40, 0.18, 3.2],
    [80+Math.cos(t*1.0)*50, 150+Math.sin(t*1.3)*45, 0.2, 2.8],
