    [300+Math.cos(t*1.4+2)*45, 200+Math.sin(t*0.7+1)*50, 0.22, 3.0]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src1){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);}
  for(const[sX,sY,f,sp]of src2){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS2+=Math.sin(d*f-t*sp);iS2+=Math.sin(d*f*0.65+t*sp*0.5+2.0);}
  const act=aS/6,inh=iS/6,act2=aS2/4,inh2=iS2/4;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*0.6)*Math.cos(sy*0.06-t*0.4)*0.15;
